unsafe extern "system" fn d3d8_texture_2d_GetLevelDesc(iface: *mut IDirect3DTexture8, level: UINT, desc: *mut D3DSURFACE_DESC) -> HRESULT {
    let texture: *mut d3d8_texture = impl_from_IDirect3DTexture8(iface);
    let mut wined3d_desc: wined3d_sub_resource_desc = core::mem::zeroed();
    let mut hr: HRESULT;

    WINE_TRACE!("iface %p, level %u, desc %p.\n", iface, level, desc);
    wined3d_mutex_lock();
    hr = wined3d_texture_get_sub_resource_desc((*texture).wined3d_texture, level, &mut wined3d_desc as *mut wined3d_sub_resource_desc);
    if hr >= 0 {
        (*desc).Format = d3dformat_from_wined3dformat(wined3d_desc.format);
        (*desc).Type = D3DRTYPE_SURFACE;
        (*desc).Usage = d3dusage_from_wined3dusage(wined3d_desc.usage, wined3d_desc.bind_flags);
        (*desc).Pool = d3dpool_from_wined3daccess(wined3d_desc.access, wined3d_desc.usage);
        (*desc).Size = wined3d_desc.size as UINT;
        (*desc).MultiSampleType = d3dmultisample_type_from_wined3d(wined3d_desc.multisample_type);
        (*desc).Width = wined3d_desc.width as UINT;
        (*desc).Height = wined3d_desc.height as UINT;
    }
    wined3d_mutex_unlock();

    return hr;
}

unsafe extern "system" fn d3d8_texture_2d_GetSurfaceLevel(iface: *mut IDirect3DTexture8, level: UINT, surface: *mut *mut IDirect3DSurface8) -> HRESULT {
    let texture: *mut d3d8_texture = impl_from_IDirect3DTexture8(iface);
    let mut surface_impl: *mut d3d8_surface = core::ptr::null_mut();

    TRACE!("iface %p, level %u, surface %p.\n", iface, level, surface);

    wined3d_mutex_lock();
    surface_impl = wined3d_texture_get_sub_resource_parent((*texture).wined3d_texture, level) as *mut d3d8_surface;
    if surface_impl.is_null() {
        wined3d_mutex_unlock();
        return D3DERR_INVALIDCALL;
    }

    *surface = core::ptr::addr_of_mut!((*surface_impl).IDirect3DSurface8_iface);
    IDirect3DSurface8_AddRef(*surface);
    wined3d_mutex_unlock();

    return D3D_OK;
}

unsafe extern "system" fn d3d8_texture_2d_LockRect(iface: *mut IDirect3DTexture8, level: UINT, locked_rect: *mut D3DLOCKED_RECT, rect: *const RECT, flags: DWORD) -> HRESULT {
    let mut texture: *mut d3d8_texture = impl_from_IDirect3DTexture8(iface);
    let mut surface_impl: *mut d3d8_surface;
    let mut hr: HRESULT;

    wined3d_mutex_lock();
    surface_impl = wined3d_texture_get_sub_resource_parent((*texture).wined3d_texture, level) as *mut d3d8_surface;
    if surface_impl.is_null() {
        hr = D3DERR_INVALIDCALL;
    } else {
        hr = IDirect3DSurface8_LockRect(core::ptr::addr_of_mut!((*surface_impl).IDirect3DSurface8_iface), locked_rect, rect, flags);
    }
    wined3d_mutex_unlock();

    return hr;
}

