unsafe extern "system" fn d3d8_texture_2d_AddDirtyRect(iface: *mut IDirect3DTexture8, dirty_rect: *const RECT) -> HRESULT {
    let texture: *mut d3d8_texture = impl_from_IDirect3DTexture8(iface);
    let mut hr: HRESULT;

    TRACE!("iface {:p}, dirty_rect {}.\n", iface, wine_dbgstr_rect(dirty_rect));

    wined3d_mutex_lock();
    if dirty_rect.is_null() {
        hr = wined3d_texture_add_dirty_region((*texture).wined3d_texture, 0, core::ptr::null::<wined3d_box>());
    } else {
        let mut dirty_region: wined3d_box = wined3d_box {
            left: 0,
            top: 0,
            right: 0,
            bottom: 0,
            front: 0,
            back: 0,
        };
        wined3d_box_set(
            core::ptr::addr_of_mut!(dirty_region),
            (*dirty_rect).left as core::ffi::c_uint,
            (*dirty_rect).top as core::ffi::c_uint,
            (*dirty_rect).right as core::ffi::c_uint,
            (*dirty_rect).bottom as core::ffi::c_uint,
            0,
            1,
        );
        hr = wined3d_texture_add_dirty_region((*texture).wined3d_texture, 0, core::ptr::addr_of_mut!(dirty_region));
    }
    wined3d_mutex_unlock();

    return hr;
}

