unsafe extern "system" fn d3d8_texture_cube_GetLevelDesc(iface: *mut IDirect3DCubeTexture8, level: UINT, desc: *mut D3DSURFACE_DESC) -> HRESULT {
    let texture: *mut d3d8_texture = impl_from_IDirect3DCubeTexture8(iface);
    let mut wined3d_desc: wined3d_sub_resource_desc = core::mem::zeroed();
    let mut hr: HRESULT = 0;

    WINE_TRACE!("iface %p, level %u, desc %p.\n", iface, level, desc);

    wined3d_mutex_lock();
    if level >= wined3d_texture_get_level_count((*texture).wined3d_texture) {
        wined3d_mutex_unlock();
        return D3DERR_INVALIDCALL;
    }

    hr = wined3d_texture_get_sub_resource_desc((*texture).wined3d_texture, level, &raw mut wined3d_desc);
    if hr >= 0 {
        (*desc).Format = d3dformat_from_wined3dformat(wined3d_desc.format);
        (*desc).Type = D3DRTYPE_SURFACE;
        (*desc).Usage = d3dusage_from_wined3dusage(wined3d_desc.usage, wined3d_desc.bind_flags);
        (*desc).Pool = d3dpool_from_wined3daccess(wined3d_desc.access, wined3d_desc.usage);
        (*desc).Size = wined3d_desc.size as UINT;
        (*desc).MultiSampleType = d3dmultisample_type_from_wined3d(wined3d_desc.multisample_type);
        (*desc).Width = wined3d_desc.width as UINT;
        (*desc).Height = wined3d_desc.height as UINT;
    }
    wined3d_mutex_unlock();

    return hr;
}

unsafe extern "system" fn d3d8_texture_cube_GetCubeMapSurface(
    iface: *mut IDirect3DCubeTexture8,
    face: D3DCUBEMAP_FACES,
    level: UINT,
    surface: *mut *mut IDirect3DSurface8,
) -> HRESULT {
    let texture: *mut d3d8_texture = impl_from_IDirect3DCubeTexture8(iface);
    let mut surface_impl: *mut d3d8_surface = core::ptr::null_mut();
    let mut sub_resource_idx: UINT = 0;
    let mut level_count: DWORD = 0;

    TRACE!(
        "iface %p, face %#x, level %u, surface %p.\n",
        iface,
        face as UINT,
        level,
        surface
    );

    wined3d_mutex_lock();
    level_count = wined3d_texture_get_level_count((*texture).wined3d_texture) as DWORD;
    if level >= level_count {
        wined3d_mutex_unlock();
        return D3DERR_INVALIDCALL;
    }

    sub_resource_idx = (level_count as UINT)
        .wrapping_mul(face as UINT)
        .wrapping_add(level);
    surface_impl = wined3d_texture_get_sub_resource_parent(
        (*texture).wined3d_texture,
        sub_resource_idx as core::ffi::c_uint,
    ) as *mut d3d8_surface;
    if surface_impl.is_null() {
        wined3d_mutex_unlock();
        return D3DERR_INVALIDCALL;
    }

    *surface = core::ptr::addr_of_mut!((*surface_impl).IDirect3DSurface8_iface);
    IDirect3DSurface8_AddRef(*surface);
    wined3d_mutex_unlock();

    return D3D_OK;
}

