unsafe extern "system" fn d3d8_texture_cube_AddDirtyRect(
    iface: *mut IDirect3DCubeTexture8,
    face: D3DCUBEMAP_FACES,
    dirty_rect: *const RECT,
) -> HRESULT {
    let texture: *mut d3d8_texture = impl_from_IDirect3DCubeTexture8(iface);
    let mut hr: HRESULT = 0;

    TRACE!(
        "iface {:p}, face {:#x}, dirty_rect {}.\n",
        iface,
        face as u32,
        wine_dbgstr_rect(dirty_rect)
    );

    wined3d_mutex_lock();
    if dirty_rect.is_null() {
        hr = wined3d_texture_add_dirty_region(
            (*texture).wined3d_texture,
            face as UINT,
            core::ptr::null::<wined3d_box>(),
        );
    } else {
        let mut dirty_region: wined3d_box = wined3d_box {
            left: 0,
            top: 0,
            right: 0,
            bottom: 0,
            front: 0,
            back: 0,
        };
        wined3d_box_set(
            core::ptr::addr_of_mut!(dirty_region),
            (*dirty_rect).left as UINT,
            (*dirty_rect).top as UINT,
            (*dirty_rect).right as UINT,
            (*dirty_rect).bottom as UINT,
            0 as UINT,
            1 as UINT,
        );
        hr = wined3d_texture_add_dirty_region(
            (*texture).wined3d_texture,
            face as UINT,
            core::ptr::addr_of_mut!(dirty_region),
        );
    }
    wined3d_mutex_unlock();

    return hr;
}

unsafe extern "system" fn d3d8_texture_3d_QueryInterface(iface: *mut IDirect3DVolumeTexture8, riid: REFIID, out: *mut *mut core::ffi::c_void) -> HRESULT {

    if IsEqualGUID!(riid, core::ptr::addr_of!(IID_IDirect3DVolumeTexture8)) != false
            || IsEqualGUID!(riid, core::ptr::addr_of!(IID_IDirect3DBaseTexture8)) != false
            || IsEqualGUID!(riid, core::ptr::addr_of!(IID_IDirect3DResource8)) != false
            || IsEqualGUID!(riid, core::ptr::addr_of!(IID_IUnknown)) != false
    {
        IDirect3DVolumeTexture8_AddRef(iface);
        *out = iface as *mut core::ffi::c_void;
        return S_OK;
    }

    WARN!("%s not implemented, returning E_NOINTERFACE.\n", debugstr_guid(riid));

    *out = core::ptr::null_mut();
    return E_NOINTERFACE;
}

