#[no_mangle]
pub unsafe extern "C" fn unsafe_impl_from_IDirect3DBaseTexture8(
    mut iface: *mut IDirect3DBaseTexture8,
) -> *mut d3d8_texture {
    if iface.is_null() {
        return core::ptr::null_mut::<d3d8_texture>();
    }

    /* SetTexture() in particular doesn't do a lot of validation on the pointer
     * that gets passed in, and passing an invalid pointer works as long as the
     * application doesn't try to actually render anything with it, so we print
     * a WARN and return NULL instead of having the usual assert() here.
     * One application affected by this is Fishdom 2. */
    if (*iface).lpVtbl != &raw const Direct3DTexture8_Vtbl as *const IDirect3DBaseTexture8Vtbl
        && (*iface).lpVtbl != &raw const Direct3DCubeTexture8_Vtbl as *const IDirect3DBaseTexture8Vtbl
        && (*iface).lpVtbl != &raw const Direct3DVolumeTexture8_Vtbl as *const IDirect3DBaseTexture8Vtbl
    {
        WARN!("%p is not a valid IDirect3DBaseTexture8 interface.\n", iface);
        return core::ptr::null_mut::<d3d8_texture>();
    }

    return (iface as ULONG_PTR).wrapping_sub(
        core::mem::offset_of!(d3d8_texture, IDirect3DBaseTexture8_iface) as ULONG_PTR,
    ) as *mut d3d8_texture;
}
unsafe extern "system" fn d3d8_texture_wined3d_object_destroyed(parent: *mut core::ffi::c_void) {
    let texture: *mut d3d8_texture = parent as *mut d3d8_texture;
    if !(*texture).draw_texture.is_null() {
        wined3d_texture_decref((*texture).wined3d_texture);
    }
    d3d8_resource_cleanup(core::ptr::addr_of_mut!((*texture).resource));
    free(texture as *mut core::ffi::c_void);
}

unsafe extern "C" fn d3d8_texture_init(texture: *mut d3d8_texture, device: *mut d3d8_device, desc: *const wined3d_resource_desc, pool: D3DPOOL, layer_count: ::core::ffi::c_uint, level_count: ::core::ffi::c_uint) -> HRESULT {
    let mut level_count = level_count;
    let mut flags: ::core::ffi::c_uint = 0;
    let mut hr: HRESULT;

    d3d8_resource_init(core::ptr::addr_of_mut!((*texture).resource));
    list_init(core::ptr::addr_of_mut!((*texture).rtv_list));

    if level_count == 0 {
        level_count = wined3d_log2i(max!(max!((*desc).width, (*desc).height), (*desc).depth)).wrapping_add(1);
    }

    if pool as ::core::ffi::c_uint == D3DPOOL_SYSTEMMEM || pool as ::core::ffi::c_uint == D3DPOOL_MANAGED {
        flags |= WINED3D_TEXTURE_CREATE_RECORD_DIRTY_REGIONS;
    }

    wined3d_mutex_lock();

    if pool as ::core::ffi::c_uint == D3DPOOL_MANAGED {
        let mut managed_desc: wined3d_resource_desc = *desc;

        managed_desc.access = WINED3D_RESOURCE_ACCESS_CPU | WINED3D_RESOURCE_ACCESS_MAP_R | WINED3D_RESOURCE_ACCESS_MAP_W;
        managed_desc.bind_flags = 0;
        hr = wined3d_texture_create(
            (*device).wined3d_device,
            core::ptr::addr_of_mut!(managed_desc),
            layer_count as UINT,
            level_count,
            flags as uint32_t,
            core::ptr::null::<wined3d_sub_resource_data>(),
            texture as *mut ::core::ffi::c_void,
            core::ptr::addr_of!(d3d8_null_wined3d_parent_ops),
            core::ptr::addr_of_mut!((*texture).wined3d_texture),
        );
        if hr < 0 {
            wined3d_mutex_unlock();
            WARN!("Failed to create sysmem texture, hr %#lx.\n", hr);
            return hr;
        }

        managed_desc.access = WINED3D_RESOURCE_ACCESS_GPU;
        managed_desc.bind_flags = (*desc).bind_flags;
        hr = wined3d_texture_create(
            (*device).wined3d_device,
            core::ptr::addr_of_mut!(managed_desc),
            layer_count as UINT,
            level_count,
            0 as uint32_t,
            core::ptr::null::<wined3d_sub_resource_data>(),
            texture as *mut ::core::ffi::c_void,
            core::ptr::addr_of!(d3d8_texture_wined3d_parent_ops),
            core::ptr::addr_of_mut!((*texture).draw_texture),
        );
        if hr < 0 {
            wined3d_texture_decref((*texture).wined3d_texture);
            wined3d_mutex_unlock();
            WARN!("Failed to create draw texture, hr %#lx.\n", hr);
            return hr;
        }
    } else {
        hr = wined3d_texture_create(
            (*device).wined3d_device,
            desc,
            layer_count as UINT,
            level_count,
            flags as uint32_t,
            core::ptr::null::<wined3d_sub_resource_data>(),
            texture as *mut ::core::ffi::c_void,
            core::ptr::addr_of!(d3d8_texture_wined3d_parent_ops),
            core::ptr::addr_of_mut!((*texture).wined3d_texture),
        );
        if hr < 0 {
            wined3d_mutex_unlock();
            WARN!("Failed to create wined3d texture, hr %#lx.\n", hr);
            return hr;
        }
    }
    wined3d_mutex_unlock();

    (*texture).parent_device = device;
    IDirect3DDevice8_AddRef(core::ptr::addr_of_mut!((*(*texture).parent_device).IDirect3DDevice8_iface));

    return D3D_OK;
}
